import{createLogger}from"#internal/logging.js";import{withSpinner}from"#setup/with-spinner.js";const log=createLogger(`setup.model-login`);async function measureLoginStage(e,t){let n=performance.now();try{return await t()}finally{log.debug(e,{elapsedMs:Math.round(performance.now()-n)})}}function withLoginProgress(e,t,n){return withSpinner(e,t,n,150)}export{measureLoginStage,withLoginProgress};